{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PARTIAL",
      "chunk_id": "text_3",
      "quote": "Although system dynamics modeling has been utilized in various aspects of public health since the 1970s, past reviews in this field have noted a significant increase in their use since the early 2000s, especially in areas focused on chronic or non-communicable diseases [24, 25]. The extent to which system dynamics modeling has been applied specifically to cancer prevention and control has not been studied.",
      "reason": "The manuscript describes the current knowledge gap (extent of application to cancer prevention/control has not been studied) but does not explicitly describe important uncertainties in the evidence base."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "To overcome persistent barriers to providing high-quality, equitable care, approaches are needed to address this complexity and provide guidance for successful intervention.",
      "reason": "The importance/need for approaches to address cancer complexity is stated, providing rationale for why a review is needed."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was retrieved showing discussion of similar systematic reviews and how the need for this review relates to updates/replications of prior reviews (including identifying and citing previous reviews)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of system dynamics modeling approaches for cancer prevention and control; the retrieved evidence does not describe an intervention effect review or a proposed mechanism of action for an intervention."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The retrieved evidence does not indicate the review is of a complex intervention or delivery context requiring a logic model to show hypothesised relationships between intervention components and outcomes."
    }
  ],
  "confidence": 62
}

