{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; 3) used system dynamics modeling (i.e., causal-loop diagramming, stock-and-flow diagramming, or computational system dynamics modeling); 4) pertained to cancer prevention or control; and 4) were published within the last 10 years.",
      "reason": "The eligibility criteria specify several study characteristics used for inclusion (e.g., peer-reviewed, English, type of modeling, cancer prevention/control, last 10 years), but the evidence does not indicate whether other requested study-characteristic components (e.g., eligible study designs and follow-up requirements) were specified."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_7",
      "quote": "Included articles: 1) were published in peer-reviewed journals; 2) were written in English; 3) used system dynamics modeling (i.e., causal-loop diagramming, stock-and-flow diagramming, or computational system dynamics modeling); 4) pertained to cancer prevention or control; and 4) were published within the last 10 years.",
      "reason": "The criteria include dissemination year restriction ('published within the last 10 years') and language ('written in English') and publication status ('peer-reviewed journals'), but the evidence does not describe other report characteristics such as exclusion/inclusion based on publication or report status beyond 'peer-reviewed journals.'"
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found describing how the review distinguishes exclusion because outcomes were not measured versus exclusion because outcome results were not reported."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence was found specifying the groups used in each synthesis or linking those groups to comparisons defined in the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_20",
      "quote": "In bounding our review to studies published in the last 10 years, we excluded older studies that could have contributed to this synthesis. We also excluded studies related to topics such as nutrition and physical activity if they did not include cancer in their models or research aims. While we feel this narrowed criteria was helpful in maintaining focus, inclusion of models more tangentially related to cancer might have provided a more comprehensive understanding of the current range of research. Due to our focus on cancer prevention and control, we also excluded studies that were solely related to cancer pathogenesis; if these were included, far more studies would be categorized as relating to etiology in the cancer control continuum.",
      "reason": "The review provides rationales for notable eligibility restrictions (e.g., last-10-years bounding, excluding certain non-cancer topics, and excluding studies solely about cancer pathogenesis) within the limitations discussion."
    }
  ],
  "confidence": 74
}

